function validate(input) {
  const [actions, values] = input;
  if (!Array.isArray(actions) || actions.length < 1 || actions.length > 10) return 'Give 1 to 10 actions.';
  if (!Array.isArray(values) || values.length !== actions.length) return 'actions and values must have the same length.';
  if (actions[0] !== 'EventEmitter') return 'The first action must be "EventEmitter".';
  const active = [];
  for (let i = 0; i < actions.length; i++) {
    const action = actions[i], args = values[i];
    if (!Array.isArray(args)) return 'Each entry of values must be a list.';
    if (action === 'EventEmitter') {
      if (i > 0 || args.length > 0) return '"EventEmitter" comes first, once, and takes no values.';
    } else if (action === 'subscribe') {
      const callback = args[1];
      const kinds = callback && typeof callback === 'object' && !Array.isArray(callback) ? Object.keys(callback) : [];
      const value = kinds.length === 1 ? callback[kinds[0]] : undefined;
      const known = kinds.length === 1 && (kinds[0] === 'returns' && ['number', 'string'].includes(typeof value) || kinds[0] === 'join' && typeof value === 'string' || kinds[0] === 'add' && typeof value === 'number');
      if (args.length !== 2 || typeof args[0] !== 'string' || !known) return 'subscribe takes an event name and a callback: {"returns": v}, {"join": separator} or {"add": k}.';
      active.push(true);
    } else if (action === 'emit') {
      if (args.length < 1 || args.length > 2 || typeof args[0] !== 'string' || (args.length === 2 && (!Array.isArray(args[1]) || args[1].some(v => typeof v !== 'number')))) return 'emit takes an event name and, optionally, a list of numbers.';
    } else if (action === 'unsubscribe') {
      if (args.length !== 1 || !Number.isInteger(args[0]) || args[0] < 0 || args[0] >= active.length) return 'unsubscribe takes the index of an earlier subscription.';
      if (!active[args[0]]) return `Subscription ${args[0]} is already cancelled.`;
      active[args[0]] = false;
    } else return 'Each action is "EventEmitter", "subscribe", "emit" or "unsubscribe".';
  }
  return null;
}

