function adapt(input, solve, kit) {
  const [actions, values] = input, answer = [], subscriptions = [];
  // Each subscribe gets a new function built from its description.
  const build = spec => {
    if ('returns' in spec) return () => spec.returns;
    if ('join' in spec) return (...args) => args.join(spec.join);
    return (...args) => args.reduce((total, x) => total + x, spec.add);
  };
  let emitter = null;
  for (let i = 0; i < actions.length; i++) {
    const [first, second] = values[i];
    if (actions[i] === 'EventEmitter') {
      emitter = new solve();
      if (!emitter || typeof emitter.subscribe !== 'function' || typeof emitter.emit !== 'function') throw new Error('EventEmitter needs subscribe and emit methods.');
      kit.trace('new EventEmitter() is created');
      answer.push([]);
    } else if (actions[i] === 'subscribe') {
      const subscription = emitter.subscribe(first, build(second));
      if (!subscription || typeof subscription.unsubscribe !== 'function') throw new Error('subscribe must return an object with an unsubscribe method.');
      subscriptions.push(subscription);
      kit.trace(`subscription ${subscriptions.length - 1}: ${JSON.stringify(second)} listens to "${first}"`);
      answer.push(['subscribed']);
    } else if (actions[i] === 'emit') {
      const results = values[i].length > 1 ? emitter.emit(first, second) : emitter.emit(first);
      if (!Array.isArray(results)) throw new Error('emit must return an array.');
      kit.trace(`emit("${first}") returns ${JSON.stringify(results)}`);
      answer.push(['emitted', results]);
    } else {
      subscriptions[first].unsubscribe();
      kit.trace(`subscription ${first} is cancelled`);
      answer.push(['unsubscribed', first]);
    }
  }
  return answer;
}

