class EventEmitter {
  constructor() {
    this.all = [];
  }

  subscribe(eventName, callback) {
    const entry = { eventName, callback, active: true };
    this.all.push(entry);
    return { unsubscribe: () => { entry.active = false; } };
  }

  emit(eventName, args = []) {
    const results = [];
    for (const entry of this.all) {
      if (entry.active && entry.eventName === eventName) results.push(entry.callback(...args));
    }
    return results;
  }
}

