function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = size === 'small' ? ['click', 'load'] : ['click', 'load', 'firstEvent'];
  const makeCallback = () => {
    const k = Math.floor(rand() * 10);
    return pick([{ returns: k }, { returns: `cb${k}` }, { join: ',' }, { join: ' ' }, { add: k }]);
  };
  const count = size === 'small' ? 1 + Math.floor(rand() * 7) : 10;
  const actions = ['EventEmitter'], values = [[]], active = [];
  while (actions.length < count) {
    const roll = rand();
    const live = active.flatMap((on, index) => (on ? [index] : []));
    if (roll < 0.35) {
      actions.push('subscribe');
      values.push([pick(names), makeCallback()]);
      active.push(true);
    } else if (roll < 0.5 && live.length > 0) {
      const index = pick(live);
      actions.push('unsubscribe');
      values.push([index]);
      active[index] = false;
    } else {
      actions.push('emit');
      const args = Array.from({ length: Math.floor(rand() * 4) }, () => Math.floor(rand() * 21) - 10);
      values.push(rand() < 0.25 ? [pick(names)] : [pick(names), args]);
    }
  }
  return [actions, values];
}
